.hide-scrollbar::-webkit-scrollbar {
    display: none
}

.hide-scrollbar {
    -ms-overflow-style: none;
    scrollbar-width: none
}

.interactive {
    transition: opacity .2s ease-in-out
}

.interactive:active {
    opacity: .5
}

.interactive:disabled {
    opacity: 1
}

.disabled-area {
    pointer-events: none;
    filter: brightness(.7);
    opacity: .8
}

.icon-full>svg {
    width: 100%;
    height: 100%
}

.input-background {
    background: linear-gradient(var(--bg-input-start), var(--bg-input-end))
}

.light-theme .input-background {
    background: var(--bg-input-end);
    border: 1px solid var(--bg-input-start)
}

