.vue-recycle-scroller.direction-horizontal {
    display: flex
}

.vue-recycle-scroller__slot {
    flex: auto 0 0
}

.vue-recycle-scroller__item-wrapper {
    flex: 1;
    box-sizing: border-box;
    overflow: hidden;
    position: relative
}

.vue-slider-disabled {
    opacity: .5;
    cursor: not-allowed
}

.vue-slider-rail {
    background-color: #ccc;
    border-radius: 15px
}

.vue-slider-process {
    background-color: #3498db;
    border-radius: 15px
}

.vue-slider-mark {
    z-index: 4
}

.vue-slider-mark:first-child .vue-slider-mark-step,
.vue-slider-mark:last-child .vue-slider-mark-step {
    display: none
}

.vue-slider-mark-step {
    width: 100%;
    height: 100%;
    border-radius: 50%;
    background-color: #00000029
}

.vue-slider-mark-label {
    font-size: 14px;
    white-space: nowrap
}

.vue-slider-dot-handle {
    cursor: pointer;
    width: 100%;
    height: 100%;
    border-radius: 50%;
    background-color: #fff;
    box-sizing: border-box;
    box-shadow: .5px .5px 2px 1px #00000052
}

.vue-slider-dot-handle-focus {
    box-shadow: 0 0 1px 2px #3498db5c
}

.vue-slider-dot-handle-disabled {
    cursor: not-allowed;
    background-color: #ccc
}

.vue-slider-dot-tooltip-inner {
    font-size: 14px;
    white-space: nowrap;
    padding: 2px 5px;
    min-width: 20px;
    text-align: center;
    color: #fff;
    border-radius: 5px;
    border-color: #3498db;
    background-color: #3498db;
    box-sizing: content-box
}

.vue-slider-dot-tooltip-inner:after {
    content: "";
    position: absolute
}

.vue-slider-dot-tooltip-inner-top:after {
    top: 100%;
    left: 50%;
    transform: translate(-50%);
    height: 0;
    width: 0;
    border-color: transparent;
    border-style: solid;
    border-width: 5px;
    border-top-color: inherit
}

.vue-slider-dot-tooltip-inner-bottom:after {
    bottom: 100%;
    left: 50%;
    transform: translate(-50%);
    height: 0;
    width: 0;
    border-color: transparent;
    border-style: solid;
    border-width: 5px;
    border-bottom-color: inherit
}

.vue-slider-dot-tooltip-inner-left:after {
    left: 100%;
    top: 50%;
    transform: translateY(-50%);
    height: 0;
    width: 0;
    border-color: transparent;
    border-style: solid;
    border-width: 5px;
    border-left-color: inherit
}

.vue-slider-dot-tooltip-inner-right:after {
    right: 100%;
    top: 50%;
    transform: translateY(-50%);
    height: 0;
    width: 0;
    border-color: transparent;
    border-style: solid;
    border-width: 5px;
    border-right-color: inherit
}

.vue-slider-dot-tooltip-wrapper {
    opacity: 0;
    transition: all .3s
}

.vue-slider-dot-tooltip-wrapper-show {
    opacity: 1
}

.v3-body-inner {
    scroll-behavior: smooth;
    scrollbar-color: #393d3f rgba(0, 0, 0, .1);
    scrollbar-width: thin
}

.v3-body-inner::-webkit-scrollbar {
    width: 8px
}

.v3-body-inner::-webkit-scrollbar-track {
    background-color: transparent
}

.v3-body-inner::-webkit-scrollbar-thumb {
    display: none;
    background: #0000004d;
    border-radius: 5px
}

.v3-body-inner:hover::-webkit-scrollbar-thumb {
    display: block
}

.v3-emoji-picker {
    height: 320px;
    width: 280px;
    box-shadow: 0 2px 10px #0003;
    border-radius: 10px;
    margin: 0 auto;
    box-sizing: border-box;
    display: flex;
    flex-direction: column;
    text-align: left
}

.v3-emoji-picker * {
    box-sizing: border-box
}

.v3-emoji-picker .v3-header {
    padding: 15px 15px 13px;
    border-bottom: 1px solid
}

.v3-emoji-picker .v3-header .v3-groups {
    display: flex
}

.v3-emoji-picker .v3-header .v3-groups .v3-group {
    flex-grow: 1;
    padding: 0;
    margin: 0;
    border: none;
    background: none;
    font-size: 23px;
    cursor: pointer;
    position: relative;
    display: block;
    opacity: .7;
    transition: .2s
}

.v3-emoji-picker .v3-header .v3-groups .v3-group.v3-is-hidden {
    display: none
}

.v3-emoji-picker .v3-header .v3-groups .v3-group:first-child,
.v3-emoji-picker .v3-header .v3-groups .v3-group:last-child {
    flex-grow: 0
}

.v3-emoji-picker .v3-header .v3-groups .v3-group:hover {
    opacity: 1
}

.v3-emoji-picker .v3-header .v3-groups .v3-group span {
    display: flex;
    align-items: center;
    justify-content: center
}

.v3-emoji-picker .v3-header .v3-groups .v3-group span img {
    display: block;
    width: 1em;
    height: auto
}

.v3-emoji-picker .v3-spacing {
    height: 11px
}

.v3-emoji-picker .v3-search input {
    width: 100%;
    display: block;
