    --v3-picker-bg: #000000;
    --v3-picker-fg: #ffffff;
    --v3-picker-border: #333333;
    --v3-picker-input-bg: #222222;
    --v3-picker-input-border: #444444;
    --v3-picker-input-focus-border: #555555;
