@keyframes load {
    0% {
        transform: rotate(0);
        border-color: rgba(128, 204, 70, 0) rgb(27, 160, 243) rgba(27, 160, 243, 0) rgb(128, 204, 70)
    }

    50% {
        transform: rotate(180deg);
        border-color: rgb(128, 204, 70) rgba(27, 160, 243, 0) rgb(27, 160, 243) rgba(128, 204, 70, 0)
    }

    to {
        transform: rotate(360deg);
        border-color: rgba(128, 204, 70, 0) rgb(27, 160, 243) rgba(27, 160, 243, 0) rgb(128, 204, 70)
    }
}

