.synthetic-scrollbar {
    text-align: left !important;
    overflow: overlay;
    scrollbar-color: transparent transparent;
    scrollbar-width: none;
    clip-path: inset(0px);
    clip: rect(auto, auto, auto, auto)
}

@supports not (overflow: overlay) {
    .synthetic-scrollbar {
        overflow: auto
    }
}

.synthetic-scrollbar:hover .v-scroll,
.synthetic-scrollbar:hover .h-scroll {
    opacity: 1
}

.synthetic-scrollbar .v-scroll,
.synthetic-scrollbar .h-scroll {
    background-color: var(--scrollbar-thumb-color) !important;
    border-radius: 4px;
    position: fixed;
    opacity: 0;
    transition: opacity .4s;
    display: inline-block;
    z-index: 10
}

.synthetic-scrollbar .v-scroll.focused,
.synthetic-scrollbar .v-scroll:hover,
.synthetic-scrollbar .h-scroll.focused,
.synthetic-scrollbar .h-scroll:hover {
    opacity: 1 !important;
    background-color: var(--scrollbar-thumb-hover-color) !important
}

.synthetic-scrollbar .v-scroll {
    width: 5px;
    margin-left: -1px
}

.synthetic-scrollbar .v-scroll.focused,
.synthetic-scrollbar .v-scroll:hover {
    margin-left: -3px;
    width: 8px
}

.synthetic-scrollbar .h-scroll {
    height: 5px;
    margin-top: -1px
}

.synthetic-scrollbar .h-scroll.focused,
.synthetic-scrollbar .h-scroll:hover {
    margin-top: -3px;
    height: 8px
}

.synthetic-scrollbar::-webkit-scrollbar {
    background-color: transparent;
    display: none
}

.synthetic-scrollbar::-webkit-scrollbar-button {
    display: none
}

.synthetic-scrollbar::-webkit-scrollbar-thumb {
    display: none
}

.synthetic-scrollbar.focused .v-scroll,
.synthetic-scrollbar.focused .h-scroll {
    opacity: 1 !important
}

