.asset-container {
    padding-top: 3px;
    margin-right: 500px;
    display: flex;
    gap: 1px;
    margin-left: 3px
}

.cell-content {
    display: flex;
    align-items: center;
    gap: 4px;
    width: 100%;
    margin-right: 15px
}

.cell-content-first:hover {
    background-color: var(--dialog-table-header-cell-hover-bg)
}

.asset-icon-quote {
    display: inline-flex;
    width: 16px !important;
    height: 16px !important;
    align-items: initial
}

.single-quote-grid {
    height: -moz-min-content;
    height: min-content;
    background-color: var(--single-quote-content-background-color);
    color: var(--dialog-table-body-font-color)
}

.single-quote-grid-content {
    width: 100%
}

.single-quote-grid-content .actions-column {
    margin: 0 5px;
    color: var(--grid-icon-tools-color);
    font-size: 14px;
    display: inline-block
}

.single-quote-grid-content .actions-column.percent {
    font-size: 15px;
    font-weight: bolder
}

.single-quote-grid-content .actions-column svg {
    height: 14px;
    width: 14px;
    vertical-align: middle
}

.single-quote-grid-content .actions-column svg path {
    fill: var(--grid-icon-tools-color)
}

.single-quote-grid-content .actions-column:hover {
    cursor: pointer
}

.single-quote-grid-content .actions-column:hover svg path {
    fill: var(--icon-tools-hover-color)
}

.single-quote-grid-content .variation-up {
    color: var(--color-positive-value) !important
}

.single-quote-grid-content .variation-down {
    color: var(--color-negative-value) !important
}

.pricebook-web-container {
    width: 100%;
    height: 100%;
    position: relative;
    overflow-y: auto
}

.pricebook-web-container .canvas {
    width: 100%;
    height: 100%;
    position: fixed
}

.pricebook-content {
    display: flex;
    flex-direction: column;
    width: 100%;
    flex-grow: 1
}

.pricebook-content-header {
    align-items: center;
    border-bottom: 1px solid var(--pricebook-header-border-color);
    display: flex;
    flex-direction: row;
    height: 20px;
    border-bottom: var(--nelo-table-border-bottom)
}

.pricebook-content-header__cell {
    color: var(--dialog-table-header-font-color);
    flex-basis: 0;
    flex-grow: 1;
    overflow: hidden;
    text-align: center;
    text-overflow: ellipsis;
    white-space: nowrap;
    height: 18px;
    display: flex;
    justify-content: center;
    align-items: center;
    background-color: var(--nelo-table-header-bg);
    margin-top: 1px
}

.pricebook-content-header__cell:last-child {
    border-right: var(--dialog-table-header-separator-color) 1px solid
}

.pricebook-content-header__cell:hover {
    background: var(--dialog-table-header-hover-background-color);
    border-bottom: var(--dialog-table-header-separator-color) 1px solid;
    border-top: var(--dialog-table-header-separator-color) 1px solid
}

.pricebook-content-header__separator {
    margin-top: 2px;
    height: 14px;
    border-left: var(--dialog-table-header-separator-color) 1px solid;
    width: 1px
}

.offerbook-web-container {
    width: 100%;
    height: 100%;
    position: relative;
    overflow-y: auto
}

.offerbook-web-container .canvas {
    width: 100%;
    height: 100%;
    position: fixed
}

.offerbook-content {
    display: flex;
    flex-direction: column;
    width: 100%;
    flex-grow: 1
}

.offerbook-content-header {
    align-items: center;
    border-bottom: var(--nelo-table-border-bottom);
    display: flex;
    flex-direction: row;
    height: 20px
}

.offerbook-content-header__cell {
    border-collapse: collapse;
    color: var(--dialog-table-header-font-color);
    flex-basis: 0;
    flex-grow: 1;
    overflow: hidden;
    text-align: center;
    text-overflow: ellipsis;
    white-space: nowrap;
    height: 18px;
    display: flex;
    justify-content: center;
    align-items: center;
    background-color: var(--nelo-table-header-bg);
    margin-top: 1px
}

.offerbook-content-header__cell:hover {
    background: var(--dialog-table-header-hover-background-color);
    border-bottom: var(--dialog-table-header-separator-color) 1px solid;
    border-top: var(--dialog-table-header-separator-color) 1px solid
}

.offerbook-content-header__cell:last-child {
    border-right: var(--dialog-table-header-separator-color) 1px solid
}

.offerbook-content-header__separator {
    border-left: var(--dialog-table-header-separator-color) 1px solid;
    height: 14px;
    width: 1px;
    margin-top: 2px
}

.alarm-content-box__inputs-container {
    display: grid;
    grid-template-columns: 1fr 1fr;
    grid-template-rows: repeat(auto-fill, 22px);
    grid-row-gap: 17px;
    grid-column-gap: 5px;
    -moz-column-gap: 5px;
    column-gap: 5px;
    padding: 20px 75px 20px 0;
    align-items: center
}

.alarm-content-box__inputs-container .sound-input {
    height: 22px
}

.alarm-content-box__inputs-container .row {
    display: flex
}

.alarm-content-box__inputs-container .row .offset-input {
    margin-right: 15px
}

.alarm-content-box__inputs-container .row-label {
    justify-self: right
}